"""Bilingual authored lesson data. Used by build.py; no runtime dependency."""
def P(zh,en): return [zh,en]
LESSONS = []
def add(id, slug, title, topic, **kw):
    LESSONS.append(dict(id=id,slug=slug,title=title,topic=topic,**kw))

add(4,'median-of-two-sorted-arrays',P('寻找两个正序数组的中位数','Median of Two Sorted Arrays'),P('二分划分','Binary partition'),
 statement=P('怎样不合并数组就找到中位数？给定两个已排序数组，返回合并序列的中间值；长度为偶数时取中间两数的平均值。输入总长度至少为 1。','How can we find the median without merging? Given two sorted arrays, return the middle value of their combined order, or the mean of the two middle values for an even length. The combined input is nonempty.'),
 constraints=P('0 ≤ m,n ≤ 1000；1 ≤ m+n ≤ 2000；值在 −10⁶…10⁶。题目要求 O(log(m+n)) 时间。','0 ≤ m,n ≤ 1000; 1 ≤ m+n ≤ 2000; values in −10⁶…10⁶. The required time is O(log(m+n)).'),
 hand=P('a=[1,3]，b=[2]。手工合并得 [1,2,3]，中位数 2。若 a=[1,2]，b=[3,4]，中间两数为 2 和 3，答案是 2.5。','For a=[1,3], b=[2], manual merging gives [1,2,3], so the median is 2. For [1,2] and [3,4], the middle pair is 2 and 3, giving 2.5.'),
 baseline='def baseline(a, b):\n    merged = sorted(a + b)\n    n = len(merged)\n    return (merged[(n - 1) // 2] + merged[n // 2]) / 2',
 cost=P('排序基线的最坏时间 O((m+n) log(m+n))、空间 O(m+n)。即使用双指针线性合并，也超过题目要求。其实只需知道中间两侧的边界。','Sorting costs O((m+n) log(m+n)) worst-case time and O(m+n) space. Even linear merging misses the required bound. Only the boundaries around the middle are needed.'),
 derive=P('先把较短数组叫 a。切口 i 表示从 a 取多少个数到左边；j=half−i，half=(m+n+1)//2，保证左半边恰好多一个或与右边一样多。两数组内部已有序，所以只需检查 aL≤bR 和 bL≤aR。','Call the shorter array a. Cut i puts i values of a on the left; j=half−i with half=(m+n+1)//2 gives the required left size. Each array is already sorted, so only aL≤bR and bL≤aR need checking.'),
 proof=P('若 aL>bR，增大 i 只会让 aL 不减、bR 不增，故排除 i 及其右侧。若 bL>aR，则反向排除左侧。空侧边界用 −∞ 或 +∞，让同一比较仍成立。只在较短数组搜索保证 j 始终合法。','If aL>bR, increasing i cannot lower aL or raise bR, so discard i and larger cuts. If bL>aR, discard smaller cuts instead. Empty-side boundaries use −∞ or +∞. Searching the shorter array keeps j within bounds.'),
 invariant=P('每次候选都满足 i+j=half；合法切口仍在 [lo,hi]。一旦交叉比较都成立，奇数长度取 max(aL,bL)，偶数长度再与 min(aR,bR) 平均。','Every candidate satisfies i+j=half; a valid cut remains in [lo,hi]. Once both cross comparisons hold, odd length uses max(aL,bL), while even length averages it with min(aR,bR).'),
 task=P('固定一组输入，移动“执行下一次操作”。观察两条切口和四个边界，先判断该往哪边移动；读数是操作后的范围，切口保留刚测试的位置；回退恢复全部状态。','Keep one input fixed and execute the next operation. Inspect both cuts and all four boundaries; predict the search direction first. The readout shows the updated search range while the cuts retain the just-tested positions; rewind restores all state.'),
 complexity=P('时间 O(log(min(m,n)+1))，额外空间 O(1)。每次至少排除一半切口；不创建合并数组。','Time O(log(min(m,n)+1)); auxiliary space O(1). Each comparison discards at least half the cuts; no merged array is created.'),
 mapping=[['i, j',P('左右分界前的元素个数','Counts of elements before the two cuts')],['al, ar, bl, br',P('切口相邻值，空侧用无穷边界','Values adjacent to cuts, with infinite empty-side sentinels')],['lo, hi',P('尚未排除的 a 切口范围','Remaining candidate cuts in a')]],
 traps=P('不要把 i 当元素下标；它是左边元素个数。两个输入不能都空。偶数时不能只返回左侧最大值；负数同样适用。','i is a count on the left, not an element index. Both inputs cannot be empty. Even length needs an average, and negative values follow the same rule.'),
 presets=[dict(label=P('奇数总长度','Odd total'),input=[[1,3],[2]]),dict(label=P('偶数与边界','Even total and boundary'),input=[[1,2],[3,4]]),dict(label=P('一个空数组','One empty array'),input=[[],[2,3]]),dict(label=P('重复与负数','Duplicates and negatives'),input=[[-3,-1,-1],[-2,-1,4]])],
 quiz=dict(question=P('新例：a=[2,6]，b=[1,3,4,5]。i=1，j=2 是否已经合法？中位数是多少？','Fresh case: a=[2,6], b=[1,3,4,5]. Is i=1, j=2 a valid cut, and what is the median?'),options=[P('合法；3.5','Valid; 3.5'),P('合法；3','Valid; 3'),P('不合法；必须增大 i','Invalid; increase i')],correct=0,feedback=[P('两边为 [2,1,3] 与 [6,4,5]；边界为 3 和 4。','The sides are [2,1,3] and [6,4,5]; the middle boundaries are 3 and 4.'),P('3 是左侧最大值，但总长度为偶数，还需要右侧最小值 4。','3 is the left maximum, but even length also needs the right minimum, 4.'),P('2≤4 且 3≤6，两个交叉比较已经成立，无需移动。','2≤4 and 3≤6 already hold; no movement is needed.')]),
 related=[(23,2,P('堆如何维护最小候选','How a heap maintains the smallest candidate')),(41,1,P('用位置保存答案线索','Use positions to encode answer clues'))])

add(10,'regular-expression-matching',P('正则表达式匹配','Regular Expression Matching'),P('前缀动态规划','Prefix dynamic programming'),
 statement=P('整个文本能否与模式匹配？小写字母必须相同，. 匹配任意一个字符，x* 表示前一元素 x 出现零次或多次。* 不能独立匹配任意串。','Does the pattern match the entire text? Lowercase letters match themselves, . matches one character, and x* repeats the preceding atom zero or more times. * is not an independent arbitrary-string matcher.'),
 constraints=P('1 ≤ 文本、模式长度 ≤ 20；每个 * 都有合法的前一元素。表中的空前缀是递推边界，不是额外的官方输入要求。','Text and pattern lengths are 1…20. Every * has a valid preceding atom. Empty prefixes in the table are recurrence boundaries, not additional official inputs.'),
 hand=P('s="aab"，p="c*a*b"：c* 取零个 c，a* 取两个 a，最后 b 匹配 b，所以为真。s="aa"，p="a" 为假，因为不能只匹配一部分。','For s="aab", p="c*a*b", take zero c characters, two a characters, then b: true. For s="aa", p="a", the answer is false because a partial match is insufficient.'),
 baseline='def baseline(s, p):\n    if not p:\n        return not s\n    first = bool(s) and p[0] in (s[0], ".")\n    if len(p) >= 2 and p[1] == "*":\n        return baseline(s, p[2:]) or (first and baseline(s[1:], p))\n    return first and baseline(s[1:], p[1:])',
 cost=P('朴素递归在 * 处尝试“跳过”与“重复”，不同路径会再次遇到相同前缀组合，最坏产生指数级分支。切片也复制字符串。把每个前缀组合只求一次即可。','Naive recursion branches into skip and repeat at *. Different paths revisit the same prefix combinations, causing exponential branching in the worst case; slicing also copies strings. Compute each prefix pair once.'),
 derive=P('dp[i][j] 表示 s 的前 i 个字符与 p 的前 j 个字符能否完全匹配。普通字符或 . 只看左上格 dp[i−1][j−1]。遇到 x*，零次用 dp[i][j−2]；一次以上要求当前字符匹配 x，再用 dp[i−1][j]。','dp[i][j] means the first i text characters fully match the first j pattern characters. An ordinary atom or . uses the diagonal dp[i−1][j−1]. For x*, zero repeats use dp[i][j−2]; one more repeat requires an atom match and dp[i−1][j].'),
 proof=P('这些情况覆盖且仅覆盖最后一段匹配：要么 x* 没用字符，要么它用了当前最后一个字符。第二种保留 j，因此还能继续重复。空串只匹配空模式或可以全部删去的 x*；dp[0][0]=真。','These cases cover exactly the last part of a match: x* consumes nothing, or consumes the last text character. Keeping j in the second case allows further repetition. Empty text matches only the empty pattern or removable x* groups; dp[0][0]=true.'),
 invariant=P('表按行计算；每个格的依赖都位于左边或上一行，已经确定。行列表示前缀长度，不是字符下标。T/F 表示真假，· 尚未计算；橙色边框标出依赖，青色标当前格。','Fill row by row; each dependency is already known to the left or above. Row and column coordinates are prefix lengths, not character indices. T/F mean true/false, · means uncomputed; orange marks dependencies and cyan marks the current cell.'),
 task=P('逐格计算，特别比较 * 列的左移两格与向上一格。保持输入不变并回退，看当前结果来自哪个已知格；表格保留此前所有结论。','Advance one cell at a time, especially the two-left and one-up dependencies of *. Rewind with the input fixed and locate the source of each result; earlier conclusions stay visible.'),
 complexity=P('时间 O(mn)，空间 O(mn)，m、n 分别为文本与模式长度。每个格只作常数次比较。','Time O(mn), space O(mn), where m and n are text and pattern lengths. Each cell uses a constant number of comparisons.'),
 mapping=[['dp[i][j]',P('两个完整前缀是否匹配','Whether the two full prefixes match')],['matches',P('当前文本字符是否匹配 * 前的元素','Whether the text character matches the atom before *')],['j - 2 / i - 1',P('跳过整组 x* / 再消费一个字符','Skip the whole x* group / consume another character')]],
 traps=P('不能用通配符题的左移一格来处理这里的 *。重复分支必须检查字符相容，不能只看上格。最终读右下格，不能看到某个 T 就停止。','Do not use the wildcard problem’s one-left star rule here. The repeat branch must check character compatibility, not only the cell above. Read the bottom-right cell, not any true cell.'),
 presets=[dict(label=P('零次与重复','Zero and repeated atoms'),input=['aab','c*a*b']),dict(label=P('不能部分匹配','Full match required'),input=['aa','a']),dict(label=P('点号加星号','Dot plus star'),input=['ab','.*']),dict(label=P('重复不能换字母','Repeat keeps its atom'),input=['ab','a*'])],
 quiz=dict(question=P('新例：s="ab"，p="a*b*"。两个 * 分别重复前面的字母，能否完全匹配？','Fresh case: s="ab", p="a*b*". Each * repeats its preceding atom. Can it match fully?'),options=[P('能：a* 取一个 a，b* 取一个 b','Yes: one a and one b'),P('不能：* 至少要重复两次','No: * must repeat at least twice'),P('能：a* 单独吞掉 ab','Yes: a* alone consumes ab')],correct=0,feedback=[P('正确。两组各消费一个字符，最终到 dp[2][4]。','Correct. Each group consumes one character, reaching dp[2][4].'),P('* 允许零次、一次或更多次，不要求两次。','* permits zero, one, or more copies; two are not required.'),P('结论碰巧为真，但理由错误：a* 不能匹配 b，必须依靠 b*。','The result happens to be true, but a* cannot consume b; b* is needed.')]),
 related=[(44,1,P('对比独立星号的递推','Compare the standalone-star recurrence')),(32,1,P('括号为何只需保存边界','Why parentheses only need boundary indices'))])

add(23,'merge-k-sorted-lists',P('合并 K 个升序链表','Merge k Sorted Lists'),P('最小堆','Min-heap'),
 statement=P('多条已排序链表如何合成一条？输入每条链表从小到大排列；输出包含所有节点的升序链表。空链表没有头节点，同值节点仍是不同对象。','How can sorted lists become one list? Each input list is ascending; return one ascending list containing all nodes. Empty lists have no head, and equal-valued nodes remain distinct objects.'),
 constraints=P('0 ≤ k ≤ 10⁴；每条长度 ≤ 500；总节点 N ≤ 10⁴；节点值 −10⁴…10⁴。','0 ≤ k ≤ 10⁴; each list length ≤ 500; total nodes N ≤ 10⁴; values −10⁴…10⁴.'),
 hand=P('[[1,4],[1,3],[2]]：先比较三个头 1、1、2。取走第一个 1 后，只需把它的后继 4 放入候选；输出依次是 1、1、2、3、4。','For [[1,4],[1,3],[2]], compare heads 1,1,2. After taking the first 1, only its successor 4 enters the candidates. The output is 1,1,2,3,4.'),
 baseline='def baseline_values(lists):\n    values = []\n    for node in lists:\n        while node:\n            values.append(node.val)\n            node = node.next\n    return sorted(values)  # oracle for values, not a linked-list return',
 cost=P('收集再排序可验证值序列，时间 O(N log N)、空间 O(N)，但还要另建或重连链表。每轮扫描全部 k 个头也要 O(Nk)。已排序的后继不可能先于自己的头被选中。','Collect-and-sort verifies values in O(N log N) time and O(N) space, but still needs list construction. Scanning all k heads each round costs O(Nk). A sorted successor cannot be chosen before its own head.'),
 derive=P('最小堆是一棵以数组保存的完全二叉树，父节点值不大于孩子；根就是所有候选中最小的。数组下标 h 的孩子是 2h+1、2h+2。只保存每条尚未耗尽链表的第一个节点。','A min-heap is a complete binary tree stored in an array; parents are no greater than children, so the root is the minimum. Array position h has children 2h+1 and 2h+2. Store only the first remaining node of each list.'),
 proof=P('取出根后，用末尾候选填补根，再与较小孩子交换，直到堆序恢复。新后继从末尾向上交换。两种操作最多沿树高 O(log k) 移动。堆不要求兄弟之间有序，所以不要把它误读成排好序的数组。','After removing the root, move the last candidate to the root and swap downward with the smaller child until heap order returns. A new successor sifts upward from the end. Each operation follows at most O(log k) levels. Siblings need not be ordered; the heap array is not sorted.'),
 invariant=P('每次弹出前，每条非空剩余链表恰好贡献一个头；全局最小剩余值必在这些头中。输出前缀有序。图中 source:index 是永久节点身份，堆括号中的 h 是存储位置。','Before each pop, each nonempty remaining list contributes exactly one head. The global remaining minimum is among those heads; the output prefix is sorted. source:index is permanent node identity; h in the heap is a storage position.'),
 task=P('逐次弹出最小头、再补入它的后继。观察堆的层级和输出历史；相同值仍显示不同的 source:index。图展示每次堆操作完成后的状态，不展示内部每次交换。','Pop the minimum head, then insert its successor. Inspect heap levels and output history; equal values keep distinct source:index labels. Frames show completed heap operations, not each internal swap.'),
 complexity=P('时间 O(k + N log(k+1))，额外空间 O(k)；输出复用输入节点。初始化必须扫描包括空链表在内的 k 个入口。','Time O(k + N log(k+1)), auxiliary space O(k); output reuses input nodes. Initialization scans all k entries, including empty lists.'),
 mapping=[['(node.val, source, node)',P('按值排序，同值用来源编号比较','Order by value, break ties with source ID')],['tail.next = node',P('把真实节点接到输出尾部','Link the actual node to the output tail')],['heappush / heappop',P('只维护 k 个以内的候选','Maintain at most k candidates')]],
 traps=P('相同值时，不能让 Python 直接比较 ListNode；source 在当前堆中唯一。空输入返回 None。数值排序 oracle 不证明节点复用，所以测试还要检查节点身份、丢失和环。','For ties, Python must not compare ListNode objects; source is unique within the heap. Empty input returns None. A value oracle cannot prove node reuse, so tests also check identities, omissions, and cycles.'),
 presets=[dict(label=P('三个候选流','Three candidate streams'),input=[[1,4,5],[1,3,4],[2,6]]),dict(label=P('空链表与同值','Empty lists and ties'),input=[[],[1,1],[1],[]]),dict(label=P('全部为空','All empty'),input=[])],
 quiz=dict(question=P('新例：[[2,7],[2,3]]。先取链表 0 的 2，补入 7。下一次应该取谁？','Fresh case: [[2,7],[2,3]]. Take list 0’s 2 and insert 7. Which node comes next?'),options=[P('链表 1 的 2','List 1’s 2'),P('链表 0 的 7','List 0’s 7'),P('链表 1 的 3','List 1’s 3')],correct=0,feedback=[P('候选头是 7 和 2；最小是链表 1 的 2。','The heads are 7 and 2; list 1’s 2 is the minimum.'),P('后继 7 只是新候选，不能跳过另一条链表的 2。','7 is only a new candidate; it cannot skip the other list’s 2.'),P('3 的前驱 2 尚未输出，当前头仍是 2。','3’s predecessor 2 has not been emitted; the current head remains 2.')]),
 related=[(25,2,P('观察节点身份与指针重连','Observe node identity and pointer rewiring')),(4,1,P('利用有序性省去合并','Use sorted order to avoid merging'))])

add(25,'reverse-nodes-in-k-group',P('K 个一组翻转链表','Reverse Nodes in k-Group'),P('指针重连','Pointer rewiring'),
 statement=P('如何每 k 个节点反转一次？只能修改节点之间的 next，不能交换节点值。末尾不足 k 个节点必须保持原顺序。','How do we reverse each group of k nodes? Change next pointers, never swap node values. A suffix shorter than k must remain in its original order.'),
 constraints=P('1 ≤ k ≤ n ≤ 5000；0 ≤ 节点值 ≤ 1000。进阶要求额外空间 O(1)。','1 ≤ k ≤ n ≤ 5000; node values 0…1000. The follow-up asks for O(1) auxiliary space.'),
 hand=P('[1,2,3,4,5]，k=2：前两组变成 [2,1] 和 [4,3]，剩下 5 保留。k=3 时只翻转第一组，得到 [3,2,1,4,5]。','For [1,2,3,4,5], k=2 gives [2,1], [4,3], then unchanged 5. With k=3, only the first group reverses, yielding [3,2,1,4,5].'),
 baseline='def baseline(head, k):\n    nodes = []\n    while head:\n        nodes.append(head)\n        head = head.next\n    for i in range(0, len(nodes) - k + 1, k):\n        nodes[i:i+k] = nodes[i:i+k][::-1]\n    for a, b in zip(nodes, nodes[1:]):\n        a.next = b\n    if nodes:\n        nodes[-1].next = None\n    return nodes[0] if nodes else None',
 cost=P('存下节点对象再反转，时间 O(n)、额外空间 O(n)，能保持身份但不满足 O(1) 进阶目标。局部反转只需保存前驱、当前节点和原后继。','Collecting node objects and reversing groups takes O(n) time and O(n) space. It preserves identities but misses the O(1) follow-up. Local reversal only needs a predecessor, current node, and saved successor.'),
 derive=P('dummy 是值无关的虚拟前驱，统一处理第一组。group_prev 指向组前节点；先向后数 k 步找 kth。找不到就直接结束。group_next=kth.next 保存组外后继；prev 初始指向它，curr 指向组头。','dummy is an artificial predecessor that makes the first group ordinary. group_prev precedes the group. Walk k links to find kth; stop if it does not exist. group_next=kth.next preserves the suffix. Start prev there and curr at the group head.'),
 proof=P('每次先保存 nxt=curr.next，再令 curr.next=prev，最后向前推进。否则改完 next 就找不到剩余节点。结束时 kth 是新组头、旧组头是新组尾；把 group_prev.next 接到 kth，再把 group_prev 移到旧组头。','Save nxt=curr.next, set curr.next=prev, then advance. Without saving nxt, overwriting next loses the unprocessed suffix. At completion kth is the new head and the old head is the new tail. Reconnect the predecessor to kth, then move group_prev to the old head.'),
 invariant=P('反转中 prev 指向已反转片段，curr 指向尚未处理片段；nxt 保存本次改线前的后继。中间状态不一定能从 head 访问所有节点，图因此保留全部节点并显式列出每条 next。读数 −1 专指 dummy，∅ 代表没有节点。','During reversal, prev leads the reversed fragment and curr leads the unprocessed fragment; nxt saves the successor before rewiring. Intermediate states need not make every node reachable from head, so the view keeps all nodes and every next pointer visible. In readouts, −1 identifies dummy and ∅ means no node.'),
 task=P('每次改一条 next，观察永久编号 # 与数值分别保持不变。对照上一帧找到被改的边，再看组与前后两部分何时重新连接。','Rewire one next at a time. Permanent # IDs and values stay fixed. Compare with the previous frame to find the changed edge and see when the group reconnects to the prefix and suffix.'),
 complexity=P('时间 O(n)、额外空间 O(1)。每个完整组只被预扫描和反转各一次；Python 不创建节点数组。','Time O(n), auxiliary space O(1). Each full group is scanned and reversed once; Python creates no node array.'),
 mapping=[['#id / node.val',P('永久对象身份 / 不变的节点值','Permanent object identity / immutable node value')],['group_prev / kth / group_next',P('组前节点 / 第 k 个 / 组后节点','Predecessor / kth node / successor')],['prev / curr / nxt',P('已反转片段 / 当前节点 / 保存的旧后继','Reversed fragment / current node / saved old successor')]],
 traps=P('不足 k 个必须在改指针之前发现。不要忘记重接前一组。值重复时不能靠值识别节点。k=1 不改变顺序，但仍应正常终止。','Detect a short group before changing any link. Reconnect the preceding group. Duplicate values cannot identify nodes. k=1 preserves order and must still terminate.'),
 presets=[dict(label=P('两两翻转','Pairs'),input=[[1,2,3,4,5],2]),dict(label=P('末尾不足一组','Short suffix'),input=[[1,2,3,4,5],3]),dict(label=P('重复值，不同节点','Equal values, different nodes'),input=[[2,2,3,3],2]),dict(label=P('k = 1','k = 1'),input=[[1,2],1])],
 quiz=dict(question=P('新例：#0=8 → #1=8 → #2=9，k=2。完成后节点编号顺序是什么？','Fresh case: #0=8 → #1=8 → #2=9, k=2. What is the final node-ID order?'),options=[P('#1 → #0 → #2','#1 → #0 → #2'),P('#0 → #1 → #2','#0 → #1 → #2'),P('#2 → #1 → #0','#2 → #1 → #0')],correct=0,feedback=[P('两个 8 的值相同，但节点对象必须交换位置；剩下 #2 不变。','The two 8s have equal values, but their objects swap positions; #2 stays last.'),P('值序列一样不等于完成了节点反转；#0 与 #1 必须互换。','An unchanged value sequence does not prove reversal; #0 and #1 must swap.'),P('只翻转完整的两节点组；#2 不属于完整组。','Only complete two-node groups reverse; #2 is not in a complete group.')]),
 related=[(23,2,P('合并链表中的节点复用','Node reuse when merging lists')),(41,2,P('对比数组中的值交换','Compare value swaps in an array'))])

add(30,'substring-with-concatenation-of-all-words',P('串联所有单词的子串','Substring with Concatenation of All Words'),P('定长滑动窗口','Word-aligned sliding window'),
 statement=P('哪些起点能连续放下全部单词？words 中所有词等长，顺序任意，但每个词必须按给定次数使用，且不能夹杂别的字符。返回所有合法起点的字符下标。','Which starts contain all words consecutively? All words have equal length and may appear in any order, but each must occur with its given multiplicity and with no gaps. Return every valid character index.'),
 constraints=P('文本长度 ≤ 10⁴；1…5000 个词；词长 1…30；均为小写字母。返回下标的顺序不限。','Text length ≤ 10⁴; 1…5000 words; word length 1…30; lowercase letters only. Output order is unrestricted.'),
 hand=P('s="barfoofoo"，words=["bar","foo"]：起点 0 给出 bar+foo，合法；起点 3 给出 foo+foo，缺 bar 且多 foo，不合法。不能只检查词是否在集合里。','For s="barfoofoo", words=["bar","foo"], start 0 gives bar+foo and is valid. Start 3 gives foo+foo, missing bar and overusing foo. Set membership alone is insufficient.'),
 baseline='from collections import Counter\n\ndef baseline(s, words):\n    w, k = len(words[0]), len(words)\n    need = Counter(words)\n    return [i for i in range(len(s) - w*k + 1)\n            if Counter(s[j:j+w] for j in range(i, i+w*k, w)) == need]',
 cost=P('每个起点重新切出 k 个词并计数，最坏 O(Lkw) 时间；相邻的同对齐窗口重复检查大量相同词。L 是字符数，k 是词数，w 是词长。','Re-splitting and counting k words at every start costs O(Lkw) worst-case time. Adjacent word-aligned windows recount many identical words. L counts characters, k words, and w characters per word.'),
 derive=P('把起点按除以 w 的余数分成 w 条扫描轨道。每条轨道 right 每次增加 w；left 是窗口左边界，图里的 right 是右端之后的字符下标。need 是所需次数，have 是当前次数，used 是词总数。','Partition starts into w tracks by their remainder modulo w. Each track advances right by w. left is the window start; the displayed right is the exclusive end. need stores required counts, have current counts, and used the number of words.'),
 proof=P('新词不在 need 中，跨过它的窗口全都无效，清空即可。若新词超额，从左端不断移走词，直到次数合法。所有词次数不超过 need 且 used=k，就必然恰好相等。记录后移走最左词，保留重叠答案的机会。','An unknown word invalidates every window crossing it, so clear the window. If a word exceeds its quota, remove words from the left until counts are valid. If every count is within need and used=k, all counts must match exactly. After recording, remove the leftmost word to allow overlapping matches.'),
 invariant=P('缩窗完成后，窗口内没有陌生词或超额词。每条轨道的 left 和 right 只前进。所有余数都扫描，才不会漏掉起点 1、2 等不从零对齐的答案。','After shrinking, the window has no unknown or excess words. left and right only move forward on each track. Scanning all remainders prevents missing starts such as 1 or 2 that are not aligned with zero.'),
 task=P('先用“重复词触发缩窗”，看 have 如何超额后恢复；再用“非零起点”，看 offset=1 找到答案。换预设会重启实验。','Use “Excess word” to watch have exceed and return to its quota. Then use “Nonzero start” to find an answer at offset=1. Changing presets restarts the experiment.'),
 complexity=P('Python 切片与字符串哈希按词长计：期望时间 O(Lw+kw)，辅助空间 O(kw)，另加输出。若将单词操作视为常数，扫描部分为 O(L)。','Accounting for Python slicing and string hashing: expected time O(Lw+kw), auxiliary space O(kw), plus output. With constant-cost word operations, the scanning portion is O(L).'),
 mapping=[['offset',P('起点对词长取余的扫描轨道','Track identified by start modulo word width')],['have / need / used',P('当前词频 / 所需词频 / 当前词数','Current counts / required counts / current number of words')],['right + width',P('图中的右开边界；Python right 是新词起点','Exclusive end in the view; Python right is the new word start')]],
 traps=P('重复词必须保留次数。缩窗必须用 while，不能只移一次。不要只扫描 offset=0。总词长大于文本时直接返回空；输出顺序可以不同。','Preserve duplicate counts. Shrink with while, not a single removal. Do not scan only offset=0. Return empty if total word length exceeds the text; answer order may differ.'),
 presets=[dict(label=P('重复词触发缩窗','Excess word'),input=['barfoofoofoobar',['bar','foo']]),dict(label=P('非零起点','Nonzero start'),input=['xbarfoo',['bar','foo']]),dict(label=P('单词本身重复','Repeated required word'),input=['foofoofoo',['foo','foo']]),dict(label=P('文本太短','Text too short'),input=['a',['aa']])],
 quiz=dict(question=P('新例：s="aaaaaa"，words=["aa","aa"]。所有合法起点是哪些？','Fresh case: s="aaaaaa", words=["aa","aa"]. Which starts are valid?'),options=[P('[0,1,2]','[0,1,2]'),P('[0,2]','[0,2]'),P('[0]','[0]')],correct=0,feedback=[P('每个长度 4 的子串都由两个 aa 组成；起点 1 来自第二条轨道。','Every length-4 substring is two aa words; start 1 comes from the second track.'),P('漏了 offset=1 轨道上的起点 1。','This misses start 1 on the offset=1 track.'),P('答案可以重叠；起点 1 和 2 也恰好含两个 aa。','Matches may overlap; starts 1 and 2 also contain exactly two aa words.')]),
 related=[(32,1,P('连续子串与无效边界','Contiguous substrings and invalid boundaries')),(41,1,P('重复值为什么改变条件','Why duplicates change the stopping rule'))])

add(32,'longest-valid-parentheses',P('最长有效括号','Longest Valid Parentheses'),P('边界栈','Boundary stack'),
 statement=P('最长连续的合法括号片段有多长？只能选连续子串，不能跳过中间坏字符。返回字符数，空串返回 0。','How long is the longest contiguous well-formed parentheses fragment? Choose a substring, never skip invalid characters inside it. Return its character count; empty text returns 0.'),
 constraints=P('0 ≤ n ≤ 30000；字符只有 ( 和 )。','0 ≤ n ≤ 30000; characters are only ( and ).'),
 hand=P('")()())" 中，从下标 1 到 4 是 "()()"，长度 4。"(()" 的合法后缀 "()" 长度只有 2；总左右括号数并不能直接给答案。','In ")()())", indices 1…4 form "()()", length 4. In "(()", the valid suffix "()" has length 2. Counting all opening and closing parentheses does not determine the answer.'),
 baseline='def baseline(s):\n    best = 0\n    for left in range(len(s)):\n        balance = 0\n        for right in range(left, len(s)):\n            balance += 1 if s[right] == "(" else -1\n            if balance < 0:\n                break\n            if balance == 0:\n                best = max(best, right - left + 1)\n    return best',
 cost=P('每个左端点都重新计算平衡，时间 O(n²)、空间 O(1)。可以只保留阻止合法后缀向左延伸的下标，而无需反复扫描。','Restarting a balance scan at each left endpoint costs O(n²) time and O(1) space. Instead, retain indices that prevent a valid suffix from extending left.'),
 derive=P('栈保存尚未匹配的左括号下标，底部还有一个无效边界，初始为 −1。遇到 ( 入栈；遇到 ) 先弹栈。若栈空，说明它无法匹配，当前 i 成为新的边界。','The stack holds unmatched opening indices above an invalid boundary, initially −1. Push on (. On ), pop first. If the stack becomes empty, this close has no match; its index i becomes the new boundary.'),
 proof=P('若弹出后仍有栈顶 t，则 t 后到 i 的每个括号都已成对，长度为 i−t。t 要么是多余左括号，要么是最近无效右括号，均不能被跨过，所以这就是以 i 结尾的最长合法后缀。','If a top t remains after the pop, every parenthesis after t through i is paired, giving length i−t. t is an unmatched opening or the last invalid closing boundary; neither can be crossed. This is the longest valid suffix ending at i.'),
 invariant=P('best 是所有已处理右端点的最长长度；length 只是当前右端点的有效后缀。栈底边界和其余未配对左括号的角色不同，不能把 −1 当输入字符。','best is the maximum over all processed endpoints; length is only the current valid suffix. The bottom boundary differs from the unmatched openings above it; −1 is not an input character.'),
 task=P('固定输入，逐个处理括号。遇到无法配对的 )，看边界如何重置；遇到配对成功的 )，看着色的连续片段与 best 的差异。','Process one parenthesis at a time. An unmatched ) resets the boundary; a matched ) highlights a contiguous suffix. Compare its length with best.'),
 complexity=P('时间 O(n)、空间 O(n)。每个下标最多入栈和出栈各一次，嵌套并不会使扫描变成平方级。','Time O(n), space O(n). Each index is pushed and popped at most once; nesting does not make the scan quadratic.'),
 mapping=[['stack[0]',P('最近不能跨过的右括号边界，初始 −1','Last uncrossable closing boundary, initially −1')],['stack[-1]',P('当前有效后缀前的边界','Boundary before the current valid suffix')],['best',P('所有已处理位置的最大值','Maximum over all processed positions')]],
 traps=P('弹栈后为空必须重设边界，不能访问 stack[-1]。不能用 i−t+1，因为 t 不属于片段。不要把子序列当子串。','If the stack empties, reset the boundary before accessing its top. Use i−t, not i−t+1, because t is excluded. A subsequence is not a substring.'),
 presets=[dict(label=P('重设边界','Reset the boundary'),input=')()())'),dict(label=P('嵌套与并列','Nested and adjacent'),input='()(())'),dict(label=P('剩余左括号','Unmatched opening'),input='(()'),dict(label=P('空串','Empty text'),input='')],
 quiz=dict(question=P('新例：s="())(())"。不能跨过下标 2 的无效右括号，最长长度是多少？','Fresh case: s="())(())". A valid substring cannot cross the invalid close at index 2. What is the longest length?'),options=[P('4','4'),P('6','6'),P('2','2')],correct=0,feedback=[P('下标 3…6 为 (())，长度 4；前面的 () 被坏字符隔开。','Indices 3…6 form (()), length 4; the earlier () is separated by an invalid close.'),P('6 把不连续的合法片段拼在了一起，跨过了无效边界。','6 joins separate valid fragments across an invalid boundary.'),P('漏掉了后面完整的嵌套片段 (())。','This misses the complete nested fragment (()) at the end.')]),
 related=[(30,2,P('滑动窗口也必须保留连续性','Sliding windows also preserve contiguity')),(10,1,P('更一般的前缀匹配状态','More general prefix matching states'))])

SUDOKU=['53..7....','6..195...','.98....6.','8...6...3','4..8.3..1','7...2...6','.6....28.','...419..5','....8..79']
SOLVED=['534678912','672195348','198342567','859761423','426853791','713924856','961537284','287419635','345286179']
add(37,'sudoku-solver',P('解数独','Sudoku Solver'),P('约束与回溯','Constraints and backtracking'),
 statement=P('如何填完 9×9 数独？每行、每列、每个 3×3 宫都要恰好包含 1…9；. 表示空格。输入保证唯一解，必须原地修改棋盘。','How can we complete a 9×9 Sudoku? Each row, column, and 3×3 box must contain 1…9 exactly once; . is empty. The input has a unique solution, and the board must be modified in place.'),
 constraints=P('固定 9×9 棋盘；每格为数字字符或 .；题目保证存在唯一解。','Fixed 9×9 board; each cell is a digit character or .; a unique solution is guaranteed.'),
 hand=P('官方例的格 (0,2)：该行排除 5、3、7，该列排除 8，该宫还排除 6、9，因此候选为 {1,2,4}。候选不等于答案：选 1 局部合法，仍可能导致后面无数可填。','At (0,2) in the official example, the row excludes 5,3,7, the column excludes 8, and the box also excludes 6,9. Candidates are {1,2,4}. A candidate is not a solution: 1 is locally valid but can lead to a later dead end.'),
 baseline='def baseline(board):\n    def valid(r, c, v):\n        return (v not in board[r]\n                and all(board[i][c] != v for i in range(9))\n                and all(board[i][j] != v\n                        for i in range(r//3*3, r//3*3+3)\n                        for j in range(c//3*3, c//3*3+3)))\n    for r in range(9):\n        for c in range(9):\n            if board[r][c] == ".":\n                for v in "123456789":\n                    if valid(r, c, v):\n                        board[r][c] = v\n                        if baseline(board):\n                            return True\n                        board[r][c] = "."\n                return False\n    return True',
 cost=P('回溯每次尝试都重扫行、列、宫以判断冲突。用集合保存已用数字可省去这些重复检查，但不会消除指数级搜索；这是常数因子的改善，不是多项式时间保证。','Backtracking repeatedly rescans rows, columns, and boxes to detect conflicts. Sets avoid these repeated checks, but do not remove exponential search. This is a constant-factor improvement, not a polynomial-time guarantee.'),
 derive=P('rows[r]、cols[c]、boxes[b] 保存已用数字，b=(r//3)*3+c//3。候选是不在这三个集合里的数。按固定空格次序尝试一个候选，进入下一个空格；若后续无解，就撤销本次选择。','rows[r], cols[c], and boxes[b] store used digits, with b=(r//3)*3+c//3. A candidate is absent from all three sets. Try one in a fixed empty-cell order and recurse to the next cell; undo the choice if no completion follows.'),
 proof=P('若某空格没有候选，当前分支不能完成，返回上一层。每次撤销必须同时恢复棋盘和三个集合，才能让下一候选在相同前提下尝试。遍历全部合法候选不会漏解；所有空格填完时，各局部约束共同保证有效解。','No candidate means this branch cannot complete, so return to the previous level. Restore both the board and all three sets before trying an alternative. Exploring every legal candidate cannot miss a solution; filling all cells while preserving constraints produces a valid board.'),
 invariant=P('每次递归入口，集合与棋盘完全一致，原始已知数不变。pos 是空格列表中的位置；r、c 是从 0 开始的棋盘坐标。candidates_at_entry 是进入当前空格时的候选，试填后仍保留。橙色表示原始已知数，青色标当前格；粗边界标出宫。','At every recursive entry, sets exactly match the board and givens are unchanged. pos indexes the empty-cell list; r,c are zero-based board coordinates. candidates_at_entry retains candidates from before trying this cell. Orange marks givens, cyan the active cell, and thick boundaries identify 3×3 boxes.'),
 task=P('官方例先出现候选 {1,2,4}。逐步尝试到一次撤销，观察空格恢复为 .；用时间滑块定位事件。长搜索只保留前 180 个事件与终局，会明确提示跳过的部分。','The official example starts with candidates {1,2,4}. Step to an undo and watch the cell return to .; use the event slider to navigate. Long searches retain the first 180 events and the final board, with an explicit omission notice.'),
 complexity=P('以 E 个空格计，保守上界 O(9^E) 时间，递归与空格表 O(E) 空间；固定 9×9 的约束集合占常量空间。约束剪枝通常减少搜索，但不改变该上界。','For E empty cells, a conservative bound is O(9^E) time and O(E) space for recursion and empty-cell positions. Constraint sets are constant-sized for a fixed 9×9 board. Pruning often reduces work without changing that upper bound.'),
 mapping=[['r, c, box',P('棋盘坐标与 3×3 宫编号','Board coordinates and 3×3 box index')],['rows / cols / boxes',P('与当前棋盘同步的已用数字集合','Used-digit sets synchronized with the board')],['search(pos + 1)',P('在当前选择下尝试填剩余空格','Try completing remaining cells under this choice')]],
 traps=P('候选少不代表当前数已经确定。失败后漏删任一集合会错误排除后续合法分支。不能修改已知数，也不能仅返回新棋盘而不修改原参数。','A small candidate set does not make a digit certain. Failing to remove a digit from any set incorrectly prunes later branches. Preserve givens and modify the original board, rather than only returning a new one.'),
 presets=[dict(label=P('官方例：含失败与撤销','Official puzzle: failures and undo'),input=SUDOKU),dict(label=P('只剩一个空格','One remaining cell'),input=['.34678912']+SOLVED[1:]),dict(label=P('已解完','Already solved'),input=SOLVED)],
 quiz=dict(question=P('新情境：给一个空格试填 4 后，下一空格没有候选。回到这个空格时该做什么？','Fresh situation: after trying 4, the next empty cell has no candidates. What must happen when returning?'),options=[P('清空该格，并从行、列、宫集合移除 4','Clear the cell and remove 4 from its row, column, and box sets'),P('只把棋盘格改回 .','Only change the board cell back to .'),P('保留 4，跳过无候选的空格','Keep 4 and skip the dead-end cell')],correct=0,feedback=[P('四处状态一起恢复，下一候选才会从同一前提开始。','All four states must be restored so the next candidate starts under the same assumptions.'),P('集合仍占用 4，会错误排除后面本该合法的分支。','The sets would still reserve 4 and incorrectly reject later valid branches.'),P('每个空格都必须填；跳过死路不能构成完整解。','Every empty cell must be filled; skipping a dead end cannot produce a complete solution.')]),
 related=[(10,1,P('分支与重复状态的区别','Branching versus repeated states')),(25,2,P('改状态前先保留恢复所需信息','Preserve needed state before mutation'))])

add(41,'first-missing-positive',P('缺失的第一个正数','First Missing Positive'),P('原地位置标记','In-place placement'),
 statement=P('无序整数中最小的缺失正数是什么？正数从 1 开始，0 和负数不算。必须在线性时间和常量额外空间内完成，可以重排输入。','What is the smallest positive integer missing from an unsorted array? Positive starts at 1; zero and negatives do not count. Use linear time and constant auxiliary space; the input may be rearranged.'),
 constraints=P('1 ≤ n ≤ 10⁵；整数在有符号 32 位范围。要求 O(n) 时间、O(1) 额外空间。','1 ≤ n ≤ 10⁵; signed 32-bit integers. Required: O(n) time and O(1) auxiliary space.'),
 hand=P('[3,4,−1,1] 含有 1 和 3，但没有 2，所以答案是 2。不是数组最小值，也不是最大值加一。','[3,4,−1,1] contains 1 and 3 but not 2, so the answer is 2. It is neither the minimum element nor necessarily the maximum plus one.'),
 baseline='def baseline(nums):\n    seen = set(nums)\n    value = 1\n    while value in seen:\n        value += 1\n    return value',
 cost=P('集合基线期望 O(n) 时间，但需要 O(n) 空间。n 个数不可能占满 1…n+1，因此答案一定在这个范围；可以直接借用原数组的 n 个位置记录 1…n。','The set baseline takes expected O(n) time but O(n) space. n values cannot occupy all of 1…n+1, so the answer lies in that range. Reuse the n array positions to record the presence of 1…n.'),
 derive=P('给数值 x 指定目标下标 x−1。只要 1≤x≤n 且目标尚不是 x，就把当前位置与目标交换。交换后当前位置得到另一个数，仍要继续检查，不能立刻推进 i。','Assign value x to index x−1. While 1≤x≤n and the destination is not already x, swap the current value with its destination. Recheck the incoming value before advancing i.'),
 proof=P('每次有效交换至少把一个数放进最终正确位置，而且已正确的位置不会被不同数移走，所以总交换次数不超过 n。若目标已有 x，继续交换只会循环；跳过重复值即可。最后第一个 nums[i]≠i+1 就暴露了缺数。','Each useful swap permanently fills at least one correct slot; a different value cannot displace it, so there are at most n swaps. If the destination already contains x, another swap would cycle; skip the duplicate. The first nums[i]≠i+1 then identifies the missing value.'),
 invariant=P('已放到 x−1 的 x 不再离开。越界数与多余副本不能占用新的有效目标；它们最终所在的缺口指出答案。图下行是目标值，上行是当前值。','Once x reaches x−1 it stays there. Out-of-range values and extra copies fill no new valid destination; the remaining gaps identify the answer. The lower row shows expected values, the upper row current values.'),
 task=P('逐次交换，固定位置看目标是否越来越多被填满；切换到重复值，观察“目标已有相同数”如何停止，而不是无限交换。','Advance through swaps and watch correct slots accumulate. Switch to duplicates and see how “destination already has this value” stops a cycle.'),
 complexity=P('时间 O(n)、额外空间 O(1)。内层 while 的总交换次数为 O(n)，并非每个 i 都可交换 n 次。输入数组会被修改。','Time O(n), auxiliary space O(1). The total number of while-loop swaps is O(n), not n for every i. The input array is mutated.'),
 mapping=[['target = nums[i] - 1',P('当前值的固定目标下标','Fixed destination index of the current value')],['nums[target] != nums[i]',P('避免重复值交换循环','Prevent duplicate-value swap cycles')],['i + 1',P('当前位置应有的正数','Positive integer expected at this position')]],
 traps=P('先检查 1≤x≤n，再访问 nums[x−1]。Python 的负下标合法但在这里语义错误。交换前保存 target，避免多重赋值下标依赖旧值造成混乱。','Check 1≤x≤n before accessing nums[x−1]. Python permits negative indexing, but it is wrong here. Save target before swapping so index evaluation cannot depend on an already changed value.'),
 presets=[dict(label=P('连续交换','Chained swaps'),input=[3,4,-1,1]),dict(label=P('重复导致的循环陷阱','Duplicate cycle trap'),input=[1,1,2]),dict(label=P('全部在范围外','All out of range'),input=[7,8,9,11,12]),dict(label=P('1 到 n 齐全','Complete 1…n'),input=[2,3,1])],
 quiz=dict(question=P('新例：[2,2,1]。把下标 0 的 2 放到目标下标 1 时，应该交换吗？最终缺数是什么？','Fresh case: [2,2,1]. Should index 0’s 2 swap with destination index 1? What is missing?'),options=[P('不交换；缺 3','Do not swap; 3 is missing'),P('一直交换直到 2 移走；缺 3','Keep swapping until 2 moves; 3 is missing'),P('不交换；缺 1','Do not swap; 1 is missing')],correct=0,feedback=[P('目标已经是 2；之后把 1 放到下标 0，第三格不是 3。','The destination is already 2. Later 1 moves to index 0, and the third slot lacks 3.'),P('交换两个 2 不改变状态，会无限循环；必须检查目标是否相同。','Swapping equal 2s changes nothing and loops forever; test destination equality.'),P('1 已在数组中，稍后会被放回正确位置。','1 is present and will later be moved to its correct slot.')]),
 related=[(25,2,P('节点重连与值交换的区别','Rewiring nodes versus swapping values')),(30,1,P('重复项与次数约束','Duplicates and multiplicity constraints'))])

add(42,'trapping-rain-water',P('接雨水','Trapping Rain Water'),P('双指针边界','Two-pointer bounds'),
 statement=P('这些宽度为 1 的柱子能存多少单位雨水？输入是非负高度；水必须同时受到左右墙限制。返回所有位置存水高度之和。','How much water fits between unit-width bars? Heights are nonnegative, and water needs a wall on both sides. Return the sum of water depths at all positions.'),
 constraints=P('1 ≤ n ≤ 20000；0 ≤ height[i] ≤ 100000。','1 ≤ n ≤ 20000; 0 ≤ height[i] ≤ 100000.'),
 hand=P('[3,0,2,0,4]：两边墙分别限制内部三个位置，水深依次是 3、1、3，总量 7。柱子本身的体积不能计作水。','For [3,0,2,0,4], the three interior positions hold depths 3,1,3, totaling 7. The bars themselves are not water.'),
 baseline='def baseline(height):\n    total = 0\n    for i, h in enumerate(height):\n        left = max(height[:i + 1])\n        right = max(height[i:])\n        total += min(left, right) - h\n    return total',
 cost=P('每格重找左右最大墙，时间 O(n²)，此 Python 切片基线临时空间 O(n)。前后缀数组可降到 O(n) 时间但用 O(n) 空间；双指针只需两个已知最大值。','Rescanning both sides costs O(n²) time; these Python slices use O(n) temporary space. Prefix/suffix maxima give O(n) time with O(n) space. Two pointers need only two running maxima.'),
 derive=P('left、right 围住尚未结算区域。left_max 包含从起点到 left 的最高墙，right_max 包含从 right 到末尾的最高墙；先把当前两端柱子纳入最大值，再比较。','left and right bound the unsettled region. left_max is the highest wall through left, and right_max the highest from right to the end. Include the current endpoint bars before comparing these maxima.'),
 proof=P('若 left_max≤right_max，左端右侧已经存在至少 left_max 高的墙，所以左端水位恰好由 left_max 决定；未知内部墙再高也改变不了这个较小限制。结算 left_max−height[left] 后推进左端。另一侧完全对称。','If left_max≤right_max, a wall at least left_max high already exists to the right. Thus the left position is limited exactly by left_max; taller unseen interior walls cannot change the smaller bound. Add left_max−height[left] and advance left. The right case is symmetric.'),
 invariant=P('指针外的位置已且仅已结算一次。图中灰块为柱高，青块为已确认的水；未结算位置没有画水不表示它最终不存水。water 是已结算总量。帧中的指针已移向下一格；最高墙在下次操作开始时刷新。','Each position outside the pointers has been settled exactly once. Gray blocks are bars, cyan blocks confirmed water; no cyan at an unsettled position does not mean it will remain dry. water is the settled total. Displayed pointers have advanced to the next cell; maxima refresh at the start of the next operation.'),
 task=P('逐格结算，先比较两个最大墙值，再观察哪端变成已结算。青色水块持续保留，最后可以逐格相加核对总量。','Settle one position at a time. Compare the two running maxima before seeing which endpoint is settled. Cyan water remains visible and can be summed at the end.'),
 complexity=P('时间 O(n)、额外空间 O(1)。每轮只移动一个指针，最多 n 轮；Python 不保存每格水量，图示为教学另行保留。','Time O(n), auxiliary space O(1). One pointer moves each round, for at most n rounds. Python stores no per-position depths; the teaching view retains them separately.'),
 mapping=[['left_max / right_max',P('已扫描两端的最高墙，不是当前柱高','Running side maxima, not current bar heights')],['left / right',P('尚未结算范围的两端','Endpoints of the unsettled range')],['water',P('已结算位置的总水量','Total water at settled positions')]],
 traps=P('用较低的最高墙决定结算侧，不要混用另一版本的判断规则。先更新最高墙再计算水量，避免负数。单柱、单调数组都存不了水。','Use the lower running maximum to choose a side; do not mix conditions from a different variant. Update maxima before computing depth to avoid negatives. A single bar or monotonic heights trap no water.'),
 presets=[dict(label=P('三个水槽位置','Three wet positions'),input=[3,0,2,0,4]),dict(label=P('官方例','Official example'),input=[0,1,0,2,1,0,1,3,2,1,2,1]),dict(label=P('单调递增','Increasing heights'),input=[1,2,3,4]),dict(label=P('单柱','Single bar'),input=[4])],
 quiz=dict(question=P('新例：[4,1,3]。中间柱上方的水深是多少？','Fresh case: [4,1,3]. What is the water depth above the middle bar?'),options=[P('2','2'),P('3','3'),P('0','0')],correct=0,feedback=[P('较低墙是 3，减去柱高 1，得到 2。','The lower wall is 3; subtract bar height 1 to get 2.'),P('3 是水位，不是水深；必须减去已有柱高 1。','3 is the water level, not depth; subtract the existing bar height 1.'),P('左右墙都比中间柱高，能围住 2 单位水。','Both walls exceed the middle bar and contain 2 units of water.')]),
 related=[(4,1,P('从边界信息推断答案','Infer an answer from boundary information')),(30,2,P('另一种只前进的双边界','Another pair of forward-only boundaries'))])

add(44,'wildcard-matching',P('通配符匹配','Wildcard Matching'),P('动态规划与滚动行','Dynamic programming and rolling rows'),
 statement=P('文本能否被通配符模式完全覆盖？? 匹配恰好一个字符，* 独立匹配任意长度的字符串，包括空串。这里的 * 不依附前一字符。','Can a wildcard pattern cover the whole text? ? matches exactly one character; standalone * matches any string, including empty. Here * does not depend on the preceding character.'),
 constraints=P('0 ≤ 文本、模式长度 ≤ 2000；小写字母、?、*。空串是正式输入。','Text and pattern lengths 0…2000; lowercase letters, ?, and *. Empty strings are official inputs.'),
 hand=P('s="adceb"，p="*a*b"：第一个 * 取空串，a 匹配 a，第二个 * 取 dce，b 匹配 b，为真。s="cb"，p="?a" 为假，? 只能解决第一个字符。','For s="adceb", p="*a*b", the first * is empty, a matches a, the second * takes dce, and b matches b: true. s="cb", p="?a" is false; ? handles only the first character.'),
 baseline='def baseline(s, p):\n    if not p:\n        return not s\n    if p[0] == "*":\n        return baseline(s, p[1:]) or (bool(s) and baseline(s[1:], p))\n    return (bool(s) and p[0] in (s[0], "?")\n            and baseline(s[1:], p[1:]))',
 cost=P('逐个尝试 * 的长度会分出大量重叠子问题，朴素递归最坏指数级。长度达 2000 时还会触发递归深度问题；迭代 DP 每个前缀组合只计算一次。','Trying lengths for each * creates overlapping subproblems and exponential worst-case recursion. Length 2000 also risks recursion depth limits. Iterative DP evaluates each prefix pair once.'),
 derive=P('dp[i][j] 表示文本前 i 个字符与模式前 j 个字符完全匹配。普通字符与 ? 从左上格转移；* 为零字符时读左格 dp[i][j−1]，再吃一个字符时读上格 dp[i−1][j]。','dp[i][j] means the first i text characters fully match the first j pattern characters. Literals and ? use the diagonal. A * consuming nothing uses the left cell dp[i][j−1]; consuming one more uses above, dp[i−1][j].'),
 proof=P('与正则 x* 不同，这里零次只跳过一个模式字符，所以是 j−1，不是 j−2。每个格只依赖当前行左侧与上一行，因此代码可只存 previous 和 current 两行；每行 current[0] 都重设为假。','Unlike regex x*, zero consumption skips only one pattern character: j−1, not j−2. Dependencies use only the current row to the left and the previous row, so code keeps just previous and current. Reset current[0] to false on every nonempty text row.'),
 invariant=P('图为解释依赖保留完整表；Python 只保留两行。行列是前缀长度，ε 是空前缀；T/F 是真假，· 尚未计算。空文本只匹配完全由 * 组成的前缀。','The view retains the full table to explain dependencies; Python stores two rows. Coordinates are prefix lengths, ε is empty, T/F mean true/false, and · means uncomputed. Empty text matches only all-star prefixes.'),
 task=P('逐格看 * 的左、上依赖；选择空串例观察第一行，再与正则题的“左移两格”比较。回退不会丢失此前已计算格。','Inspect the left and above dependencies of *. Choose the empty-text case to study row zero, then compare regex’s two-left rule. Rewinding restores previously computed cells.'),
 complexity=P('时间 O((m+1)(n+1))、额外空间 O(n)，n 为模式长度。常用简写 O(mn) 默认非空；空串初始化仍需 O(n)。','Time O((m+1)(n+1)), auxiliary space O(n), with n the pattern length. The usual O(mn) shorthand assumes nonempty inputs; initializing empty text still costs O(n).'),
 mapping=[['previous[j]',P('上一行同列：dp[i−1][j]','Same column in the previous row: dp[i−1][j]')],['current[j - 1]',P('当前行左格：dp[i][j−1]','Left cell in the current row: dp[i][j−1]')],['previous[j - 1]',P('左上依赖，用于普通字符或 ?','Diagonal dependency for literals or ?')]],
 traps=P('不要混入正则题的 . 和 x* 规则。不能因为末尾有 * 就忽略前面不匹配的字符。更新新行必须清空，避免上一行的真值泄漏。','Do not import regex’s . and x* rules. A trailing * cannot repair an earlier mismatched literal. Clear each new row so previous true values do not leak into it.'),
 presets=[dict(label=P('任意长度星号','Variable-length star'),input=['adceb','*a*b']),dict(label=P('问号仍需匹配剩余','Question mark is not enough'),input=['cb','?a']),dict(label=P('空串与多个星号','Empty text and repeated stars'),input=['','**']),dict(label=P('非空文本，空模式','Nonempty text, empty pattern'),input=['a',''])],
 quiz=dict(question=P('新例：s="ab"，p="a*"。此题能匹配吗？与正则题有何不同？','Fresh case: s="ab", p="a*". Does this problem match it, and how does regex differ?'),options=[P('此题为真，正则为假','Wildcard true, regex false'),P('两题都为真','Both true'),P('两题都为假','Both false')],correct=0,feedback=[P('通配符 * 独立吞掉 b；正则 a* 只能重复 a，不能匹配 b。','Wildcard * independently consumes b; regex a* only repeats a and cannot match b.'),P('正则 a* 不会吞任意字符，它不能匹配最后的 b。','Regex a* does not consume arbitrary characters; it cannot match the final b.'),P('本题的 * 可以匹配任意后缀，包括单个 b。','Here * can match any suffix, including a single b.')]),
 related=[(10,1,P('对照正则 x* 的两格跳跃','Compare regex x* skipping two columns')),(32,1,P('用更小的状态表达边界','Represent boundaries with less state'))])

# Fixed question-specific order avoids teaching that the first option is always right.
for lesson in LESSONS:
    quiz = lesson['quiz']
    shift = lesson['id'] % len(quiz['options'])
    for field in ('options', 'feedback'):
        quiz[field] = quiz[field][shift:] + quiz[field][:shift]
    quiz['correct'] = (quiz['correct'] - shift) % len(quiz['options'])
